using Builder.Core;
using System.Collections.Immutable;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Xml.Linq;

internal static class SurfacePaintChecks
{
    public static async Task Run(string root,string? evidenceRoot=null)
    {
        var output=evidenceRoot??Path.Combine(root,".local/evidence/surface-paint-20261021/core");Directory.CreateDirectory(output);
        var input=Path.Combine(root,".local/evidence/surface-paint-20261021/inputs");var worker=Path.Combine(root,"prototypes/Builder/Builder.GeometryWorker/bin/win-x64/Builder.GeometryWorker.exe");
        var cases=new List<string>();var outputs=new List<object>();var red=new SurfaceMaterial("Red",new(214,82,72));var blue=new SurfaceMaterial("Blue",new(38,124,181));
        EditorSession New()=>new(worker);
        async Task<EditorSession> Load(string name){var s=New();Ok(await s.OpenAsync(Path.Combine(input,name+".3mf")));return s;}
        async Task Paint(EditorSession s,Guid id,int face,SurfaceMaterial? material,SurfacePaintMode mode=SurfacePaintMode.ConnectedSurface,Guid? scope=null)
        {Ok(await s.PreviewSurfaceMaterialAsync(new(id,face,material,mode){MemberGroupId=scope}));Ok(s.ApplyPreview(s.Snapshot.Preview!.Id));}
        void Pass(string name){cases.Add(name);Console.WriteLine("PASS "+name);}
        async Task Save(EditorSession s,string name)
        {
            var file=Path.Combine(output,name+".3mf");Ok(await s.SaveAsync(file));var reader=New();Ok(await reader.OpenAsync(file));Check(reader.Snapshot.Scene.Objects.Length==s.Snapshot.Scene.Objects.Length,"Save lost objects.");
            for(var i=0;i<s.Snapshot.Scene.Objects.Length;i++){var a=s.Snapshot.Scene.Objects[i];var b=reader.Snapshot.Scene.Objects[i];Check(a.Name==b.Name&&a.Material==b.Material&&a.TriangleMaterials.OrderBy(p=>p.Key).SequenceEqual(b.TriangleMaterials.OrderBy(p=>p.Key))&&a.Transform==b.Transform,"Face material/name/placement roundtrip failed.");}
            outputs.Add(new{name,path=Path.GetFileName(file),sha256=Hash(file),objects=s.Snapshot.Scene.Objects.Select(o=>new{o.Name,o.Material,o.Bounds,triangles=o.Mesh.Triangles.Length,overrides=o.TriangleMaterials.OrderBy(p=>p.Key).Select(p=>new{triangleIndex=p.Key,material=p.Value})})});
        }

        var s=New();Ok(s.Execute(new AddCube()));var id=s.Snapshot.SelectedObjectId!.Value;var unassigned=s.Snapshot;var mesh=unassigned.Scene.Objects[0].Mesh;
        Ok(await s.PreviewSurfaceMaterialAsync(new(id,2,red)));var p=s.Snapshot.Preview!;Check(p.SurfaceMaterial!.TriangleIndices.SequenceEqual(new[]{2,3})&&ReferenceEquals(p.Scene.Objects[0].Mesh,mesh)&&p.Scene.Objects[0].Material==SurfaceMaterial.Neutral,"Flat region/neutral promotion changed geometry or region.");Check(p.SelectedObjectIds.SequenceEqual(unassigned.SelectedObjectIds),"Paint changed selection.");Ok(s.ApplyPreview(p.Id));Ok(s.Undo());Check(ReferenceEquals(s.Snapshot.Scene,unassigned.Scene),"Undo failed to restore unassigned scene.");Ok(s.Redo());
        await Paint(s,id,6,blue,SurfacePaintMode.Triangle);Check(s.Snapshot.Scene.Objects[0].GetTriangleMaterial(6)==blue&&s.Snapshot.Scene.Objects[0].GetTriangleMaterial(7)==SurfaceMaterial.Neutral,"Single-triangle paint expanded.");await Save(s,"painted-cube");var saved=s.Snapshot;Ok(s.Undo());Check(s.Snapshot.IsDirty&&s.Snapshot.Scene.Objects[0].TriangleMaterials.Count==2,"Undo across saved paint failed.");Ok(s.Redo());Check(ReferenceEquals(s.Snapshot.Scene,saved.Scene)&&!s.Snapshot.IsDirty,"Redo saved paint lost clean state.");
        var alias=New();Ok(await alias.OpenAsync(Path.Combine(root,"fixtures/generated/cube-20mm.stl")));var hit=alias.Snapshot.Scene.PickRay(new(10,10,50),new(0,0,-1))!;Ok(alias.Execute(new RotateObject(hit.ObjectId,new(15,20,30))));Ok(await alias.PreviewSurfaceMaterialAsync(new(hit.ObjectId,hit.TriangleIndex,red)));Check(alias.Snapshot.Preview!.SurfaceMaterial!.TriangleIndices.Length==2,"World edge welding failed on STL aliases/transformed face.");
        Pass("Connected flat region and single-triangle modes preserve geometry/selection, weld STL aliases after world transforms, promote neutral fallback and support exact Undo/Redo/save");

        var group=await Load("surface-group");var original=group.Snapshot;Check(original.Scene.Objects[0].TriangleMaterials.Count==4&&original.Scene.Objects[1].TriangleMaterials.Count==1,"Fixture triangle properties parsed incorrectly.");await Save(group,"painted-group");
        var subset=Path.Combine(output,"painted-subset.3mf");var before=group.Snapshot;Ok(await group.ExportSelectionAsync(subset,[before.Scene.Objects[0].Id]));Same(group,before);var reader=New();Ok(await reader.OpenAsync(subset));Check(reader.Snapshot.Scene.Groups.Length==1&&reader.Snapshot.Scene.Objects[0].TriangleMaterials.Count==4&&reader.Snapshot.Scene.Objects[1].TriangleMaterials.Count==1,"Selection export lost distinct face maps.");
        outputs.Add(new{name="painted-subset",path=Path.GetFileName(subset),sha256=Hash(subset)});
        var inserted=New();Ok(inserted.Execute(new AddCube()));Ok(await inserted.InsertAsync(Path.Combine(input,"surface-group.3mf")));Check(inserted.Snapshot.Scene.Objects.Skip(1).Select(o=>o.TriangleMaterials.Count).SequenceEqual(new[]{4,1}),"Insert dropped painted faces.");
        foreach(var bad in new[]{"gradient","missing-default"}){before=group.Snapshot;Check((await group.OpenAsync(Path.Combine(input,bad+".3mf"))).Outcome==Outcome.Invalid,"Unsupported triangle import accepted.");Same(group,before);}
        var oldTriangle=New();Ok(await oldTriangle.OpenAsync(Path.Combine(root,".local/evidence/paint-materials-20261021/inputs/triangle-material.3mf")));
        // A pid-only triangle inherits the object PROPERTY, not the same index in the other resource.
        var partial=Path.Combine(output,"pid-only.3mf");File.Copy(Path.Combine(input,"surface-cube.3mf"),partial,true);XNamespace core="http://schemas.microsoft.com/3dmanufacturing/core/2015/02";
        using(var zip=ZipFile.Open(partial,ZipArchiveMode.Update)){var entry=zip.GetEntry("3D/3dmodel.model")!;XDocument doc;using(var stream=entry.Open())doc=XDocument.Load(stream);var resources=doc.Root!.Element(core+"resources")!;resources.AddFirst(new XElement(core+"basematerials",new XAttribute("id",999),new XElement(core+"base",new XAttribute("name","Other"),new XAttribute("displaycolor","#000000FF"))));var triangle=doc.Descendants(core+"triangle").First();triangle.SetAttributeValue("pid",999);entry.Delete();using(var stream=zip.CreateEntry("3D/3dmodel.model").Open())doc.Save(stream);}
        var defaults=New();Ok(await defaults.OpenAsync(partial));Check(defaults.Snapshot.Scene.Objects[0].GetTriangleMaterial(0)==defaults.Snapshot.Scene.Objects[0].Material,"pid-only triangle changed fallback.");
        Pass("Standard object defaults and uniform triangle p1/p2/p3 persist in grouped distinct maps, insert/subset; pid-only uses object property, gradients/missing defaults refuse atomically");

        var scoped=await Load("surface-group");id=scoped.Snapshot.Scene.Objects[0].Id;var scope=scoped.Snapshot.Scene.Groups.Single().Id;before=scoped.Snapshot;Check((await scoped.PreviewSurfaceMaterialAsync(new(id,2,blue))).Outcome==Outcome.Invalid,"Scene-scope member surface accepted.");Same(scoped,before);Ok(scoped.EnterGroup(scope,id));before=scoped.Snapshot;
        var request=new SurfaceMaterialRequest(id,2,blue){MemberGroupId=scope};Ok(await scoped.PreviewSurfaceMaterialAsync(request));var first=scoped.Snapshot.Preview!;Ok(await scoped.PreviewSurfaceMaterialAsync(request with{TriangleIndex=4},first.Id));var held=scoped.Snapshot;
        Check(held.Preview!.Id!=first.Id&&held.Preview.Scene.Objects[0].GetTriangleMaterial(2)==red&&ReferenceEquals(held.Preview.Scene.Objects[1],before.Scene.Objects[1])&&held.Preview.Scene.Groups.Single()==before.Scene.Groups.Single(),"Replacement accumulated region or changed sibling/group.");
        foreach(var bad in new[]{request with{TriangleIndex=-1},request with{AngleToleranceDegrees=91},request with{Material=red with{Name=" "}}}){Check((await scoped.PreviewSurfaceMaterialAsync(bad,held.Preview.Id)).Outcome==Outcome.Invalid,"Invalid paint accepted.");Same(scoped,held);}
        Check((await scoped.PreviewSurfaceMaterialAsync(request,first.Id)).Outcome==Outcome.Conflict&&(await scoped.PreviewSurfaceMaterialAsync(request,held.Preview.Id,expectedRevision:before.Revision-1)).Outcome==Outcome.Conflict,"Stale paint accepted.");Same(scoped,held);
        foreach(var stage in new[]{"before","Finding surface region","Ready to preview surface paint"}){using var ct=new CancellationTokenSource();if(stage=="before")ct.Cancel();Check((await scoped.PreviewSurfaceMaterialAsync(request,held.Preview.Id,ct.Token,new Progress(x=>{if(x.Stage==stage)ct.Cancel();}))).Outcome==Outcome.Cancelled,"Cancel failed: "+stage);Same(scoped,held);}
        using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var ct=new CancellationTokenSource())
        {var job=scoped.PreviewSurfaceMaterialAsync(request,held.Preview.Id,ct.Token,new Progress(x=>{if(x.Stage=="Finding surface region"){entered.Set();Check(release.Wait(10000),"Barrier timeout.");}}));Check(entered.Wait(10000),"Paint did not start.");Check(scoped.Select(null).Outcome==Outcome.Busy&&scoped.ApplyPreview(held.Preview.Id).Outcome==Outcome.Busy,"Busy guards failed.");ct.Cancel();release.Set();Check((await job).Outcome==Outcome.Cancelled,"Busy cancel failed.");Same(scoped,held);}
        Check(scoped.DiscardPreview(held.Preview.Id).Outcome==Outcome.Cancelled,"Discard failed.");Same(scoped,before);
        Ok(await scoped.PreviewSurfaceMaterialAsync(new(id,2,red){MemberGroupId=scope}));Ok(scoped.ApplyPreview(scoped.Snapshot.Preview!.Id));Same(scoped,before); // Exact no-op includes revision, history, clean state and full selection.
        await Paint(scoped,id,2,null,scope:scope);Check(!scoped.Snapshot.Scene.Objects[0].TriangleMaterials.ContainsKey(2)&&scoped.Snapshot.Scene.Objects[0].Material==before.Scene.Objects[0].Material,"Surface clear did not restore fallback.");Ok(scoped.Undo());Check(ReferenceEquals(scoped.Snapshot.Scene,before.Scene),"Clear Undo not exact.");Ok(scoped.ExitGroup());var exited=scoped.Snapshot;Check((await scoped.PreviewSurfaceMaterialAsync(request)).Outcome==Outcome.Conflict,"Stale member authority accepted.");Same(scoped,exited);
        Pass("Member ownership, fresh same-object replacement, no-op Apply, clear/Undo and stale/busy/cancel guards preserve selection, group, accepted document and prior candidate");

        var preservation=await Load("surface-cube");id=preservation.Snapshot.SelectedObjectId!.Value;var sourceObject=preservation.Snapshot.Scene.Objects[0];Ok(await preservation.PreviewTransformAsync(new MirrorTransform(id,MirrorAxis.X)));var mirrored=preservation.Snapshot.Preview!.Scene.Objects[0];Check(mirrored.Mesh.Triangles.Length==sourceObject.Mesh.Triangles.Length&&Enumerable.Range(0,12).All(i=>mirrored.GetTriangleMaterial(i)==sourceObject.GetTriangleMaterial(i)),"Mirror detached triangle colors.");Ok(preservation.ApplyPreview(preservation.Snapshot.Preview.Id));Ok(preservation.Execute(new DuplicateObject(id)));Check(preservation.Snapshot.Scene.Objects.All(o=>o.TriangleMaterials.Count==4),"Duplicate lost painted faces.");await Save(preservation,"mirrored-duplicates");
        var pieces=New();Ok(await pieces.OpenAsync(Path.Combine(root,".local/evidence/separate-20261020/inputs/two-hollow-boxes.3mf")));id=pieces.Snapshot.SelectedObjectId!.Value;await Paint(pieces,id,0,red,SurfacePaintMode.Triangle);await Paint(pieces,id,pieces.Snapshot.Scene.Objects[0].Mesh.Triangles.Length-1,blue,SurfacePaintMode.Triangle);sourceObject=pieces.Snapshot.Scene.Objects[0];Ok(await pieces.PreviewSeparateAsync(new(id)));p=pieces.Snapshot.Preview!;
        foreach(var part in p.Separate!.Pieces){var obj=p.Scene.Objects.Single(o=>o.Id==part.ObjectId);for(var i=0;i<part.SourceTriangleIndices.Length;i++)Check(obj.GetTriangleMaterial(i)==sourceObject.GetTriangleMaterial(part.SourceTriangleIndices[i]),"Separate did not remap exact source face colors.");}Ok(pieces.ApplyPreview(p.Id));await Save(pieces,"painted-separated");
        Pass("Mirror retains face-index colors, duplicate retains overrides and Separate explicitly remaps source triangle provenance to editable pieces; native saves retain maps");

        var refusal=await Load("surface-cube");id=refusal.Snapshot.SelectedObjectId!.Value;Ok(refusal.Execute(new AddCube()));var other=refusal.Snapshot.SelectedObjectId!.Value;before=refusal.Snapshot;
        var outline=new OutlineTextSource(new([ImmutableArray.Create(new Vec2(0,0),new Vec2(1,0),new Vec2(1,1),new Vec2(0,1))]));
        GeometryRequest[] remesh=[new SplitRequest(id,new(1,0,0),10),new BooleanRequest(id,other,BooleanKind.Union),new RepairRequest(id),new HollowRequest(id),new SimplifyRequest(id),new SmoothRequest(id),new ExtrudeDownRequest(id),new EmbossRequest(id,outline,new(EmbossFace.PositiveZ),1)];
        foreach(var operation in remesh){var r=await refusal.PreviewAsync(operation);Check(r.Outcome==Outcome.Invalid&&r.Message.Contains("surface colors",StringComparison.Ordinal),"Remeshing lost colors or gave unclear refusal: "+operation.GetType().Name);Same(refusal,before);}
        Ok(await refusal.PreviewMaterialAsync(new([id],before.Scene.Objects[0].Material)));Check(refusal.Snapshot.Preview!.Scene.Objects[0].TriangleMaterials.Count==0,"Whole-object same-base paint did not clear overrides.");Ok(refusal.ApplyPreview(refusal.Snapshot.Preview.Id));Ok(refusal.Undo());Check(ReferenceEquals(refusal.Snapshot.Scene,before.Scene),"Whole-object repaint Undo lost surfaces.");
        var invalid=new Scene(Guid.NewGuid(),[new(Guid.NewGuid(),"Invalid",Mesh.Cube,Affine.Identity){TriangleMaterials=ImmutableDictionary<int,SurfaceMaterial>.Empty.Add(0,red)}]);try{invalid.Validate();throw new Exception("Override without base accepted.");}catch(ModelException){}
        var atomic=Path.Combine(output,"atomic-save.3mf");File.Copy(Path.Combine(input,"surface-cube.3mf"),atomic,true);var hash=Hash(atomic);var saveBefore=refusal.Snapshot;using(var ct=new CancellationTokenSource()){Check((await refusal.SaveAsync(atomic,ct.Token,new Progress(x=>{if(x.Stage=="Ready to save")ct.Cancel();}))).Outcome==Outcome.Cancelled,"Cancel painted save failed.");}Check(Hash(atomic)==hash,"Cancelled save replaced file.");Same(refusal,saveBefore);
        Pass("Topology-changing tools refuse painted operands clearly; whole-object repaint clears overrides undoably, validation requires fallback, and cancelled save keeps existing file");
        File.WriteAllText(Path.Combine(output,"surface-paint-results.json"),JsonSerializer.Serialize(new{timestamp=DateTimeOffset.UtcNow,scenarioCount=cases.Count,cases,outputs,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,
            core=new{path=typeof(EditorSession).Assembly.Location,sha256=Hash(typeof(EditorSession).Assembly.Location)},worker=new{path=worker,sha256=Hash(worker)},inputs=Directory.GetFiles(input,"*.3mf").Select(path=>new{path,sha256=Hash(path)}),
            limitations="Opaque uniform-per-triangle overrides, connected normals relative to seed (default1degree) or explicit triangle. No brush radius, gradients or textures; STL geometry-only. First paint can explicitly assign Neutral fallback. Remeshing refuses surface colors except provenance-mapped Separate; Mirror keeps triangle indices. No worker changes."},new JsonSerializerOptions{WriteIndented=true}));
        Console.WriteLine($"{cases.Count} surface paint groups passed. Evidence: {output}");
    }
    private sealed class Progress(Action<OperationProgress> action):IProgress<OperationProgress>{public void Report(OperationProgress p)=>action(p);}
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static void Ok(OperationResult result)=>Check(result.Succeeded,result.ToString());
    private static void Same(EditorSession session,EditorSnapshot before)=>Check(session.Snapshot==before,"Accepted or prior candidate state changed.");
    private static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
}
